stylesheet:
QWidget {
    background-color: #1e2430;
    color: #d8dee9;
    font-family: 'Poppins', 'Inter', 'Segoe UI', sans-serif;
    font-size: 13px;
}
QLineEdit {
    background-color: #212a38;
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 7px;
    padding: 6px 10px;
    color: #d8dee9;
}
QLineEdit:focus {
    border: 1px solid rgba(136,192,208,0.55);
    background-color: #2e3f55;
}
QLineEdit:disabled {
    color: #28303e;
    background-color: #18202c;
    border-color: rgba(255,255,255,0.04);
}
QRadioButton {
    spacing: 8px;
    color: #d8dee9;
}
QRadioButton::indicator {
    width: 14px; height: 14px;
    border-radius: 7px;
    border: 1px solid rgba(255,255,255,0.2);
    background: transparent;
}
QRadioButton::indicator:checked {
    background-color: rgba(136,192,208,0.85);
    border: 1px solid rgba(136,192,208,0.7);
}
QPushButton {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.09);
    border-radius: 7px;
    padding: 0 14px;
    height: 30px;
    color: #88c0d0;
    font-size: 12px;
}
QPushButton:hover {
    background: rgba(255,255,255,0.09);
    border-color: rgba(255,255,255,0.15);
    color: #eceff4;
}
QPushButton:pressed { background: rgba(255,255,255,0.13); }
QPushButton:disabled {
    color: #202830;
    background: rgba(255,255,255,0.02);
    border-color: rgba(255,255,255,0.04);
}
QPushButton[role="primary"] {
    background: rgba(136,192,208,0.18);
    border: 1px solid rgba(136,192,208,0.38);
    color: #88c0d0;
    font-weight: 600;
}
QPushButton[role="primary"]:hover {
    background: rgba(136,192,208,0.3);
    border-color: rgba(136,192,208,0.55);
    color: #a8d8e8;
}
QPushButton[role="primary"]:pressed { background: rgba(136,192,208,0.44); }
QPushButton[role="primary"]:disabled {
    background: rgba(136,192,208,0.07);
    border-color: rgba(136,192,208,0.12);
    color: rgba(136,192,208,0.3);
}
QScrollBar:vertical {
    background: transparent; width: 4px; margin: 0; border: none;
}
QScrollBar::handle:vertical {
    background: #354560; border-radius: 2px; min-height: 20px;
}
QScrollBar::handle:vertical:hover { background: rgba(136,192,208,0.45); }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical,
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    height: 0; border: none; background: transparent;
}
QScrollBar:horizontal {
    background: transparent; height: 4px; margin: 0; border: none;
}
QScrollBar::handle:horizontal {
    background: #354560; border-radius: 2px; min-width: 20px;
}
QScrollBar::handle:horizontal:hover { background: rgba(136,192,208,0.45); }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal,
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    width: 0; border: none; background: transparent;
}

QLineEdit {
    background: #242d3a;
    border: 1px solid rgba(255,255,255,0.09);
    border-radius: 10px;
    padding: 0 8px;
    color: #d8dee9;
    font-size: 11px;
    selection-background-color: rgba(136,192,208,0.35);
}
QLineEdit:focus {
    border-color: rgba(136,192,208,0.45);
    background: #242d3a;
}

QWidget#projectDriveCard {
    background-color: #242d3a;
    border: 1px solid rgba(255,255,255,0.11);
    border-radius: 10px;
}

QWidget#projectDriveCard {
    background-color: #2f3a4d;
    border: 1px solid rgba(255,255,255,0.11);
    border-radius: 10px;
}

QProgressBar {
    border: none;
    background-color: rgba(255,255,255,0.1);
    border-radius: 2px;
}
QProgressBar::chunk {
    background-color: #F25D91;
    border-radius: 2px;
}

QWidget#projectDriveCard {
    background-color: #2f3a4d;
    border: 1px solid rgba(255,255,255,0.11);
    border-radius: 10px;
}

QProgressBar {
    border: none;
    background-color: rgba(255,255,255,0.1);
    border-radius: 2px;
}
QProgressBar::chunk {
    background-color: #9368F5;
    border-radius: 2px;
}

QListWidget {
    background: transparent;
    border: none;
    padding: 8px 16px;
    outline: 0;
}

/* ITEM CARD */
QListWidget::item {
    background-color: #242d3a;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.07);
    padding: 6px 14px;
    margin-bottom: 8px;
}
QListWidget::item:hover {
    background-color: #2e3f55;
    border: 1px solid rgba(136,192,208,0.3);
}
QListWidget::item:selected {
    background-color: rgba(136,192,208,0.12);
    border: 1px solid rgba(136,192,208,0.45);
}
QListWidget::item:selected:!active {
    background-color: rgba(136,192,208,0.12);
    border: 1px solid rgba(136,192,208,0.45);
}

/* FOCUS OUTLINE */
QListWidget::item:!selected {
    outline: 0;
}

QListWidget::item:selected {
    outline: 0;
}
/* =========================
SCROLLBAR TOTAL HIDE (0px)
========================= */
QScrollBar:vertical {
    width: 0px;
    background: transparent;
    margin: 0px;
}

QScrollBar::handle:vertical {
    width: 0px;
    min-height: 0px;
}

QScrollBar::add-line:vertical,
QScrollBar::sub-line:vertical,
QScrollBar::add-page:vertical,
QScrollBar::sub-page:vertical {
    width: 0px;
    height: 0px;
    background: none;
}
/* =========================
HORIZONTAL SCROLLBAR (TIDURAN)
========================= */
QScrollBar:horizontal {
    height: 0px;
    min-height: 0px;
    max-height: 0px;
    background: transparent;
}

QScrollBar::handle:horizontal,
QScrollBar::add-line:horizontal,
QScrollBar::sub-line:horizontal,
QScrollBar::add-page:horizontal,
QScrollBar::sub-page:horizontal {
    height: 0px;
    background: transparent;
}

font-size: 12px;
font-weight: 600;
color: #eceff4;
